import fs from 'node:fs';
import assert from 'node:assert/strict';
import {TRACKS,worldNumber} from '../../src/tracks.js';
const market=JSON.parse(fs.readFileSync(new URL('./technical-market-data.json',import.meta.url),'utf8'));
const course=JSON.parse(fs.readFileSync(new URL('../../src/content/technical-curriculum-v1.json',import.meta.url),'utf8'));
const track=TRACKS.find(t=>t.id==='technical');
const round=n=>Math.round(n*100)/100,fmt=n=>new Intl.NumberFormat('es-ES',{maximumFractionDigits:2}).format(n);
const C=(body,correct,wrong,explanation)=>({type:'choice',title:'Elige la conclusión que se sostiene',body,options:[{text:wrong[0]},{text:correct},...wrong.slice(1).map(text=>({text}))],answer:1,explanation,hint:'Busca qué dato apoya la respuesta y qué parte sería una suposición.'});
const M=(body,options,answers,explanation)=>({type:'multi',title:'Selecciona todas las correctas',body,options:options.map(text=>({text})),answers,explanation,hint:'Revisa cada afirmación por separado; no basta con que una palabra suene familiar.'});
const numericHints={
 'return':'Resta el valor inicial al final, divide entre el inicial y multiplica por cien. Conserva el signo.',
 'difference':'Resta las dos referencias en el orden que indica la pregunta. Comprueba si se pide una distancia o un cambio con signo.',
 'range-percent':'Calcula máximo menos mínimo, divide entre la apertura indicada y multiplica por cien.',
 'projection':'Calcula primero la altura entre techo y referencia. Después resta esa altura a la referencia inferior.',
 'mean':'Suma los valores que incluye la pregunta y divide entre su cantidad; no añadas otros días.',
 'rsi':'Divide la subida media entre la bajada media. Usa esa relación dentro de la fórmula indicada, respetando los paréntesis.',
 'true-range':'Compara máximo menos mínimo y las dos distancias absolutas al cierre anterior. Elige la mayor, sin sumarlas.',
 'weighted-price':'Multiplica cada precio por su volumen. Suma los productos y divide entre la suma de volúmenes.',
 'loss-with-cost':'Calcula lo perdido entre compra y venta, y añade los costes totales una sola vez.',
 'floor-ratio':'Divide el presupuesto entre la pérdida por unidad. Si solo se admiten unidades enteras, redondea hacia abajo.',
 'expectancy-total':'Suma lo ganado por todos los aciertos y réstale lo perdido por todos los fallos.',
 'net-trades':'Multiplica el número de operaciones por el coste de cada una y réstalo al resultado bruto.',
 'ratio-percent':'Divide la parte indicada entre el total de la muestra y multiplica por cien.',
 'product':'Multiplica la cantidad de unidades por la pérdida estimada de cada una.',
 'retracement':'Calcula la amplitud entre los extremos, toma el porcentaje indicado de esa amplitud y réstalo al extremo superior.',
};
const N=(body,answer,unit,explanation,operands,operation)=>({type:'numeric',title:'Haz la cuenta con estos datos',body,answer:round(answer),tolerance:.02,unit,explanation,hint:numericHints[operation]||'Identifica las cantidades y la unidad que pide la pregunta antes de operar.',calculation:{operands,operation}});
const P=(body,pairs,explanation)=>({type:'match',title:'Relaciona las ideas',body,pairs:pairs.map(([left,right])=>({left,right})),explanation,hint:'Distingue lo que se observa de lo que se decide después.'});
const O=(body,items,explanation)=>({type:'order',title:'Ordena el procedimiento',body,items,answer:items.map((_,i)=>i),explanation,hint:'Los criterios se definen antes de consultar el resultado.'});
const L=(title,body,takeaway)=>({type:'learn',title,body,takeaway,visual:'none'});
const F=(caption,headers,rows)=>({kind:'table',caption,headers,rows});
const flow=(caption,items)=>({kind:'flow',caption,items});
const definitions=[];
// Each case has three purpose-written explanation/challenge pairs. Real prices are
// supplied separately; rounded educational trade plans never masquerade as history.
function add(title,goals,pairs,comparison){definitions.push({title,goals,pairs,comparison});}
add('El precio cuenta una historia, pero no el futuro',['Separar un movimiento observado de una predicción','Identificar qué no se puede conocer con un gráfico'],[
 [L('Describe antes de explicar','Estás viendo precios realmente negociados, no una línea dibujada para que parezca fácil. Mira el primer y el último cierre: esa comparación permite describir el cambio durante el tramo. No explica por sí sola por qué alguien compró ni lo que ocurrirá al día siguiente. Una hipótesis añade una condición que se podría comprobar después. Escribir «si el próximo cierre supera el máximo del tramo, revisaré la idea» es distinto de asegurar «mañana subirá».','Una observación habla de los datos disponibles; una predicción añade algo que todavía no sabemos.'),C('Al terminar de mirar el gráfico, ¿qué frase distingue bien observación y predicción?','Puedo describir el tramo mostrado; para hablar del siguiente día necesito una hipótesis, no una certeza.',['El último movimiento continuará porque aparece en un gráfico.','El precio me dice cuánto dinero genera el proyecto.'],'El gráfico contiene operaciones pasadas. No contiene la certeza sobre el siguiente cierre ni las cuentas del proyecto.')],
 [L('Comparar exige el mismo punto de partida','Para medir un cambio se divide la diferencia entre el precio inicial. Practiquemos con cifras inventadas, separadas del mercado real: de 40 a 44 euros, el aumento es 4 y el cambio es 4 / 40 × 100 = 10 %. El porcentaje permite comparar inversiones de precios distintos. No es un beneficio tuyo si no compraste al inicio y vendiste al final, y todavía habría que descontar costes si estuvieras calculando una operación.','Cambio porcentual = diferencia / precio inicial × 100.'),N('Ejemplo simulado: un precio pasa de 50 a 55 €. ¿Qué subida porcentual representa? Escribe el porcentaje.',10,'%', '(55 − 50) / 50 × 100 = 10 %. Es el cambio del precio, antes de costes.',[55,50],'return')],
 [L('Una idea útil puede resultar equivocada','Una hipótesis útil deja claro qué estás observando y qué dato te haría cambiar de opinión. No necesita prometer un beneficio. Imagina que, al cierre del gráfico, escribes tu previsión y después aparece una noticia que cambia el comportamiento del mercado. Eso no modifica el precio que ya estaba registrado. Sí puede invalidar tu interpretación. La habilidad que entrenamos es revisar una explicación con datos nuevos, sin inventar motivos que el gráfico no permite demostrar.','Corregir una interpretación es compatible con haber descrito bien los datos.'),M('Marca las dos afirmaciones que podrías defender usando un gráfico histórico.',['Los cierres representan precios pasados.','Una subida demuestra quién compró y por qué.','Una hipótesis puede fallar con datos nuevos.','Una forma del gráfico garantiza el día siguiente.'],[0,2],'El registro de precios es observable; las intenciones y el futuro no lo son.')]
 ],['Descripción','Separar el movimiento registrado de lo que imaginas que pasará.','Predicción sin condición','Tratar el próximo día como si ya figurara en el gráfico.']);
add('Ocho días que no son ocho operaciones',['Leer apertura, máximo, mínimo y cierre','Distinguir el periodo del gráfico y la duración de una inversión'],[
 [L('Cada vela resume un día completo','En este caso, cada vela japonesa reúne las operaciones de un día UTC: desde las 00:00 hasta justo antes de las 00:00 siguientes. La apertura es la primera operación, el cierre la última, y los extremos son el mayor y el menor precio negociados. Una vela verde termina por encima de su propia apertura; no obliga a terminar por encima del cierre del día anterior. Puedes tocar una vela y comprobar sus cuatro precios en el inspector.','El color compara apertura y cierre de esa misma vela.'),M('Selecciona las dos lecturas correctas para estas velas diarias ya cerradas.',['Cada vela equivale a una compra tuya.','Una vela verde puede cerrar por debajo del cierre anterior.','El máximo es necesariamente el último precio.','Los extremos recogen el máximo y el mínimo de ese día.'],[1,3],'La vela resume muchas operaciones. Su color usa apertura y cierre del mismo día; los extremos no fijan el último precio.')],
 [L('Un día puede ocultar un recorrido muy distinto','Dos días pueden compartir apertura y cierre y, sin embargo, tener máximos y mínimos muy distintos. La línea de cierres ocultaría esa diferencia; las velas la conservan. Eso tampoco permite reconstruir el orden exacto de todas las operaciones intradía. Si un día tocó 90 y 110 euros, la vela diaria no dice qué extremo alcanzó primero. Para una pregunta sobre el orden de ejecución necesitarías datos de intervalos más cortos o el registro de operaciones.','Una vela conserva extremos, pero no toda la secuencia de precios.'),P('Relaciona cada pregunta con el dato necesario. No supongas información que no se muestra.',[['¿Dónde terminó el día?','Cierre'],['¿Hasta dónde bajó durante el día?','Mínimo'],['¿Tocó primero el máximo o el mínimo?','Información intradía adicional']],'El cierre y el mínimo están resumidos en la vela. El orden de ambos extremos no lo está.')],
 [L('Medir el recorrido del día','El rango diario es la distancia entre el máximo y el mínimo. En un ejemplo simulado, una vela con máximo 110 y mínimo 100 tiene un rango de 10 euros, aunque abra y cierre en 105. No ha acabado con una variación entre apertura y cierre, pero sí ha recorrido precios diferentes. El rango describe amplitud; la resta entre cierre y apertura describe dirección neta dentro de ese periodo. Son preguntas distintas sobre los mismos cuatro datos.','Un cierre sin cambio puede esconder un día de movimientos amplios.'),N('Vela simulada: apertura 102 €, máximo 112 €, mínimo 98 € y cierre 102 €. ¿Cuál es su rango, en euros?',14,'€','112 − 98 = 14 €. El rango utiliza los extremos, no la apertura y el cierre.',[112,98],'difference')]
 ],['Solo cierres','Una línea sirve para comparar dónde termina cada día, pero oculta los extremos.','Velas completas','Apertura, máximo, mínimo y cierre ayudan a distinguir días con el mismo cierre y diferente recorrido.']);
add('Una tendencia necesita algo más que la última vela',['Comparar máximos y mínimos en orden temporal','Distinguir retroceso y cambio de estructura'],[
 [L('Busca una secuencia, no un color','Para describir una tendencia interesa cómo se suceden los extremos relevantes, no cuántas velas verdes hay. Una estructura de máximos y mínimos crecientes combina avances y retrocesos que siguen quedándose por encima de referencias anteriores. La última vela puede ser roja dentro de esa estructura. Tampoco todo pequeño extremo merece la misma importancia: selecciona referencias comparables y di qué tramo estás usando. Si cambias de referencia cada vez que una conclusión no te gusta, ya no estás aplicando un criterio estable.','La dirección de una vela y la estructura del tramo son cosas distintas.'),C('En el gráfico aparece una última vela roja. ¿Qué necesitas antes de afirmar que toda la tendencia ha cambiado?','Compararla con los máximos y mínimos relevantes anteriores.',['Contar el color de esa vela y olvidarme del resto.','Saber si la vela ocupa más espacio en mi pantalla.'],'Una vela roja muestra caída respecto a su apertura. El cambio de estructura requiere compararla con referencias anteriores.')],
 [L('Un ejemplo donde el retroceso no rompe la estructura','Practiquemos con una secuencia inventada para fijar el criterio: mínimo 90, máximo 100, mínimo 94 y máximo 106 euros. Hay un mínimo y un máximo posteriores superiores a sus referencias anteriores. Si después el precio retrocede a 98, continúa por encima de 94. Ese retroceso no rompe todavía el último mínimo elegido. Haber mantenido una referencia no garantiza una nueva subida: solo permite describir lo que, hasta ese instante, aún no se ha invalidado.','No llames giro a cualquier retroceso; señala qué referencia se ha perdido.'),N('Secuencia simulada: último mínimo relevante 94 €, máximo posterior 106 € y retroceso hasta 98 €. ¿Cuántos euros separan 98 de ese mínimo de referencia?',4,'€','98 − 94 = 4 €. La referencia sigue por debajo; esto no pronostica el siguiente movimiento.',[98,94],'difference')],
 [L('Haz que otra persona pueda revisar tu lectura','Un análisis claro nombra el periodo, señala los extremos escogidos y explica qué observación lo cambiaría. No basta con escribir «tendencia fuerte» sin definir fuerte ni identificar referencias. Para describir este gráfico real, empezarías por sus fechas y después consultarías los precios de los extremos. Si los extremos no forman una secuencia clara, puedes decirlo: un resultado indeterminado es mejor que forzar una etiqueta. La herramienta ayuda a comparar; no obliga a encontrar una tendencia en cada ventana.','Es válido concluir que este tramo no basta para clasificar la estructura.'),O('Ordena una lectura que otra persona pueda comprobar.',['Fijar el tramo y el periodo de las velas','Elegir máximos y mínimos con el mismo criterio','Comparar las referencias en orden temporal','Anotar qué dato invalidaría la lectura'],'Primero se define la muestra; después se eligen y comparan referencias. La invalidación completa una hipótesis revisable.')]
 ],['Retroceso contenido','Un movimiento contrario que conserva el mínimo elegido no prueba todavía un giro.','Referencia perdida','Perder ese mínimo obliga a revisar la estructura, aunque no garantice una caída posterior.']);
add('Una zona es una referencia, no una barrera',['Marcar zonas de soporte y resistencia','Separar un contacto de una reacción confirmada'],[
 [L('No todos compran al mismo céntimo','Un soporte es una zona donde anteriormente aparecieron compras suficientes para frenar una caída; una resistencia es una zona donde se frenó un avance. Son descripciones del pasado, no muros que detengan obligatoriamente el futuro. En un mercado real los contactos rara vez coinciden en un único céntimo. Al revisar las velas, busca agrupaciones de extremos y cierres, y describe un intervalo razonable. Dibujar una zona tan ancha que incluya todo el gráfico tampoco aporta una referencia útil.','Las zonas ayudan a formular preguntas, no garantizan rebotes.'),P('Relaciona cada observación con lo que permite decir.',[['Varias caídas se frenaron en un intervalo','Posible zona de soporte'],['Varios avances se frenaron en un intervalo','Posible zona de resistencia'],['El precio toca por primera vez mi línea','Todavía no prueba un rebote']],'El papel de una zona depende de las reacciones observadas. Un contacto aislado no confirma lo que sucederá después.')],
 [L('Cuánto margen estás dando a la zona','La anchura de la zona hace explícita la tolerancia de tu lectura. En un ejemplo inventado, un soporte entre 95 y 100 euros abarca 5 euros. No es equivalente a una línea en 100: un precio de 98 sigue dentro del intervalo. Define también si tu criterio usa un cierre fuera de la zona o basta un extremo intradía. Sin esa distinción, dos personas pueden interpretar de manera opuesta exactamente la misma vela y creer que están aplicando la misma regla.','Una zona necesita límites y una regla para interpretar el cierre.'),N('Zona simulada de 95 a 100 €. Un día marca mínimo 93 € y cierra en 97 €. ¿Cuántos euros queda el cierre por encima del límite inferior de 95 €?',2,'€','97 − 95 = 2 €. El mínimo salió de la zona, pero el cierre terminó dentro.',[97,95],'difference')],
 [L('Describe lo ocurrido sin mover la portería','Antes de consultar el día siguiente, deja escritos los límites y el criterio de ruptura. Si después desplazas la zona para que todo parezca un acierto, la comparación pierde sentido. En este gráfico real puedes observar dónde hubo contactos, pero no atribuirles automáticamente intenciones a los participantes. Una forma honesta de redactar sería «el cierre volvió al intervalo marcado». «Los grandes inversores defendieron el precio» necesitaría información adicional que la vela por sí sola no proporciona.','Mantén el criterio original para poder evaluar si funcionó.'),M('Selecciona las dos prácticas que permiten evaluar una zona sin engañarte.',['Fijar sus límites antes de mirar el siguiente resultado.','Moverla después de cada fallo para que parezca respetada.','Distinguir un mínimo fuera de la zona de un cierre fuera.','Afirmar que una zona impide perder dinero.'],[0,2],'Los límites previos y la diferencia entre extremos y cierres permiten revisar la interpretación con el mismo criterio.')]
 ],['Mecha fuera','El extremo sale de la zona pero el cierre vuelve dentro: no cumple una regla que exija cierre exterior.','Cierre fuera','El periodo termina fuera: cumple esa condición, aunque la ruptura todavía pueda fallar.']);
add('Volumen: actividad que necesita contexto',['Comparar actividad entre periodos equivalentes','Evitar atribuir intenciones a una barra de volumen'],[
 [L('Qué se está contando','Debajo de estas velas puedes consultar cuánto se negoció en Coinbase Exchange durante cada día. Es volumen de este mercado concreto, expresado en unidades del activo; no reúne automáticamente todas las plataformas del mundo. Un día con más volumen indica más cantidad intercambiada aquí. Cada intercambio tiene comprador y vendedor, así que una barra alta por sí sola no demuestra que «solo había compradores». Para interpretar la actividad conviene compararla con días equivalentes y con el recorrido del precio.','Más volumen significa más cantidad negociada en la fuente indicada.'),M('Selecciona las dos conclusiones compatibles con los datos de este caso.',['El volumen pertenece al mercado y al periodo indicados.','Una barra alta demuestra que nadie vendió.','Para comparar actividad diaria necesito periodos de igual duración.','Coinbase representa necesariamente todo el mercado mundial.'],[0,2],'La fuente y el periodo delimitan la comparación. Toda compraventa incluye ambos lados y la serie no cubre todas las plataformas.')],
 [L('Una referencia para comparar','Decir «mucho volumen» exige una referencia. En una simulación, cuatro días completos negocian 80, 100, 120 y 100 unidades: la media es 100. Un quinto día de 150 unidades queda un 50 % por encima de esa media. Estamos comparando cantidades, no contando personas ni midiendo cuánto dinero nuevo entró. Una sola persona puede realizar muchas operaciones. Mantén igual unidad, mercado y duración para que la comparación responda a la pregunta planteada.','Compara el volumen con una referencia explícita, en las mismas unidades.'),N('Ejemplo simulado: el volumen habitual es 200 unidades por día y hoy, ya cerrado el día, se negocian 300. ¿En qué porcentaje supera 300 a 200?',50,'%','(300 − 200) / 200 × 100 = 50 %. Son unidades negociadas, no personas.',[300,200],'return')],
 [L('Precio y actividad responden a preguntas diferentes','El precio informa de dónde terminaron los intercambios; el volumen informa de cuánto se intercambió. Juntos permiten describir mejor una sesión, pero no identifican el motivo de cada participante. Una subida acompañada de actividad superior a la referencia puede ser compatible con interés en el movimiento. También puede acabar fallando al día siguiente. En tu nota del caso conserva ambos datos, la referencia elegida y la condición de invalidación, en lugar de convertir la coincidencia en una promesa.','El volumen aporta contexto, no una garantía de continuación.'),C('Una vela cierra al alza con volumen superior a la media elegida. ¿Qué anotación es más precisa?','Hubo subida y más actividad que la referencia; aún no sé si continuará.',['La subida de mañana ya está confirmada.','Cada comprador nuevo garantiza una subida adicional.'],'La comparación describe esa sesión. No determina lo que harán los participantes después.')]
 ],['Un día completo','Una barra diaria terminada se puede comparar con otros días completos.','Media jornada','Una barra parcial requiere esperar o utilizar una referencia de igual duración.']);
add('Moverse mucho no es lo mismo que subir',['Medir el rango del precio','Separar amplitud y dirección'],[
 [L('Dos preguntas sobre una misma sesión','Al mirar las velas, puedes preguntar dónde terminó cada día o cuánto se movió entre sus extremos. La primera cuestión tiene que ver con dirección; la segunda, con amplitud. Un día puede recorrer una distancia grande y terminar casi donde empezó. Por eso no describimos la volatilidad como una forma de decir «subida». En este caso trabajamos con el rango, máximo menos mínimo, una medida sencilla de amplitud diaria; otras medidas de volatilidad utilizan series completas de cambios.','Un rango amplio puede acompañar una subida, una caída o un cierre casi plano.'),P('Une cada pregunta con la comparación adecuada.',[['¿Terminó por encima de la apertura?','Cierre frente a apertura'],['¿Qué distancia hubo entre extremos?','Máximo menos mínimo'],['¿Subirá necesariamente mañana?','No se deduce de la amplitud pasada']],'La amplitud y la dirección son descripciones diferentes. Ninguna convierte el siguiente día en una certeza.')],
 [L('Comparar amplitudes con precios distintos','Un rango de 5 euros pesa de forma distinta si la referencia del precio es 50 o 500 euros. Para una comparación sencilla dividimos el rango entre una base que nombramos expresamente. Por ejemplo, rango 5 sobre apertura 50 equivale al 10 % de esa apertura. No estamos calculando la rentabilidad: el precio no tuvo que empezar en el mínimo ni terminar en el máximo. Esa diferencia evita confundir el recorrido del mercado con una ganancia que alguien obtuvo realmente.','El rango relativo mide amplitud respecto a la base elegida.'),N('Vela simulada: apertura 100 €, máximo 108 € y mínimo 96 €. Divide el rango entre la apertura. ¿Qué porcentaje obtienes?',12,'%','El rango es 108 − 96 = 12. 12 / 100 × 100 = 12 % de la apertura.',[108,96,100],'range-percent')],
 [L('Una referencia para adaptar la lectura','Si los rangos recientes se amplían, una distancia que antes parecía grande puede quedar dentro del movimiento habitual de una sola sesión. Eso invita a revisar el criterio de interpretación, no a aumentar automáticamente lo que arriesgas. El gráfico real te permite comparar varios días con la misma escala y la misma duración. Antes de sacar una conclusión, comprueba también que no hayas cambiado de euros a otra moneda o de velas diarias a semanales: ambas cosas alterarían la comparación.','Mantén comparables unidad y periodo antes de hablar de más o menos amplitud.'),M('Marca las dos comparaciones útiles para estudiar si ha cambiado la amplitud.',['Rangos de varios días completos en el mismo mercado.','Una vela semanal frente a un minuto, sin ajustar la duración.','Rangos relativos calculados con la misma base.','El tamaño visual de la vela después de cambiar el zoom.'],[0,2],'Comparar la misma duración y la misma definición de rango relativo evita que la escala de pantalla decida por ti.')]
 ],['Rango amplio y cierre plano','El día recorre muchos precios, aunque apertura y cierre sean parecidos.','Rango pequeño y cierre positivo','Puede terminar al alza habiendo recorrido una distancia pequeña.']);
add('Una vela llamativa no basta para decidir',['Distinguir cuerpo y mechas','Interpretar doji y martillos dentro de su contexto'],[
 [L('La forma empieza por una proporción','El cuerpo es la distancia entre apertura y cierre; las mechas muestran lo recorrido por encima y por debajo del cuerpo. Un doji tiene apertura y cierre muy próximos en relación con el rango, aunque no siempre exactamente iguales. Un cuerpo pequeño no cuenta todo el día: puede convivir con mechas largas. Un martillo presenta cuerpo pequeño, mecha inferior larga respecto al cuerpo y poca mecha superior; para interpretarlo como posible giro alcista se examina si aparece después de una caída. En el gráfico real consulta los cuatro precios antes de asignar un nombre. El color por sí solo no permite saber si el cuerpo es pequeño respecto al recorrido completo.','La forma se define con proporciones; el nombre no sustituye la medición.'),C('Una vela tiene cuerpo pequeño y rango amplio. ¿Qué dato adicional necesitas para llamarla martillo con sentido?','La distribución de las mechas y el contexto anterior.',['Solo comprobar que es verde.','El número de unidades que yo querría comprar.'],'Un martillo requiere una forma concreta, especialmente una mecha inferior larga; su interpretación depende del tramo previo.')],
 [L('Hacer visible la proporción','Usemos una vela inventada: apertura 100, cierre 101, mínimo 95 y máximo 102 euros. El cuerpo mide 1, la mecha inferior 5 y la superior 1. La mecha inferior va del mínimo al menor de apertura y cierre; no se mide hasta el máximo. Esta separación permite comprobar si una etiqueta describe la figura. Aunque la mecha inferior sea larga, solo muestra que el precio regresó desde niveles inferiores durante ese periodo, sin asegurar el cierre siguiente.','Calcula cada parte con sus extremos correctos.'),N('Vela simulada: apertura 100 €, cierre 102 €, mínimo 94 € y máximo 103 €. ¿Cuántos euros mide la mecha inferior?',6,'€','El borde inferior del cuerpo es 100. La mecha inferior mide 100 − 94 = 6 €.',[100,94],'difference')],
 [L('Qué haría falta después de la forma','Una vela de posible giro se interpreta junto a lo que la precede y a lo que ocurre después. Un cuerpo pequeño en mitad de un movimiento lateral puede tener un significado distinto del que le atribuirías tras varias caídas. Tampoco debes usar datos futuros como si ya estuvieran disponibles al cierre de esa vela. Deja anotada una condición para revisar la hipótesis en la sesión siguiente. Si esa condición no ocurre, el dibujo conserva su forma, pero la idea de continuación no queda confirmada.','Forma, contexto y confirmación son tres comprobaciones separadas.'),O('Ordena la revisión de una vela que te llama la atención.',['Medir cuerpo y mechas con los cuatro precios','Examinar el movimiento que la precede','Escribir qué confirmación pedirías después','Comprobar esa condición cuando exista el dato'],'El dato posterior sirve para evaluar una hipótesis previa, no para inventarla después de conocer el resultado.')]
 ],['Cuerpo pequeño en un rango lateral','La forma no demuestra por sí sola que vaya a empezar una tendencia.','Forma parecida después de una caída','Invita a estudiar una posible reacción, sin dar el giro por hecho.']);
add('Envolventes: compara cuerpos, no impresiones',['Comprobar una envolvente con precios','Separar patrón visual y señal operativa'],[
 [L('Qué envuelve a qué','En una envolvente comparamos los cuerpos de dos velas consecutivas. En la versión alcista habitual, una primera vela bajista es seguida por una alcista cuyo cuerpo abarca el anterior. No basta con que la segunda tenga una mecha muy larga. Tampoco basta con que sea verde. Los límites de cada cuerpo son su apertura y su cierre. En mercados que negocian de forma continua, como estos pares, la continuidad entre sesiones puede hacer que algunas fronteras coincidan: declara si admites esa igualdad en tu criterio.','Una envolvente de cuerpos se comprueba con aperturas y cierres.'),M('Marca las dos afirmaciones correctas al buscar una envolvente.',['Debo comparar los límites de ambos cuerpos.','Una mecha larga demuestra que un cuerpo contiene al otro.','Conviene declarar cómo trato la igualdad entre límites.','Cualquier pareja roja y verde es una envolvente.'],[0,2],'El color no basta. Son necesarias las relaciones de precios entre cuerpos y una definición coherente del patrón.')],
 [L('Probar el criterio con números','En un ejemplo simulado, la primera vela abre en 105 y cierra en 101: su cuerpo va de 101 a 105. La siguiente abre en 100 y cierra en 106: su cuerpo contiene el anterior y además termina por encima de su propia apertura. Esa pareja cumple una definición estricta de envolvente alcista de cuerpos. Si solo cambiara el máximo de la segunda vela a 106 pero cerrara en 103, el cuerpo ya no cubriría todo el primero, aunque la mecha alcanzara más alto.','El cierre de la segunda vela puede cambiar la clasificación aunque su máximo sea igual.'),P('Relaciona cada segunda vela simulada con el cuerpo de referencia 101–105, aplicando contención estricta.',[['Cuerpo de 100 a 106','Contiene completamente el cuerpo anterior'],['Cuerpo de 102 a 104','Queda dentro del cuerpo anterior'],['Cuerpo de 103 a 108','Se solapa, pero no lo contiene']],'Contener requiere cubrir tanto el límite inferior como el superior. Una parte en común solo es solapamiento.')],
 [L('El patrón no incluye una rentabilidad prometida','Identificar correctamente una envolvente es una tarea descriptiva. Decidir operar exigiría además contexto, condición de entrada, límite de pérdida y costes. Una pareja de velas puede cumplir el criterio geométrico y después no ir en la dirección esperada. Para estudiar si una regla fue útil necesitarías muchas observaciones definidas del mismo modo, incluidas las que fallaron. Escoger solo una imagen bonita del pasado no aporta esa comprobación y puede producir una confianza que los datos no justifican.','Clasificar una forma no demuestra que una estrategia sea rentable.'),C('En una situación hipotética, una pareja sí cumple el criterio de envolvente. ¿Qué conclusión sería válida?','He identificado el patrón definido; todavía no he demostrado una ventaja para operar.',['La operación tiene beneficio garantizado.','Las mechas han dejado de importar para medir el riesgo.'],'La geometría se puede comprobar en dos velas. La utilidad de una estrategia necesita una muestra y reglas adicionales.')]
 ],['Envolvente de cuerpos','El segundo cuerpo abarca el primero según la regla declarada.','Solo una mecha más larga','El extremo supera al anterior, pero el cuerpo puede no contenerlo.']);
add('Tres velas: una secuencia que hay que comprobar',['Comparar el avance de tres cierres','Evitar reconocer patrones usando datos futuros'],[
 [L('Tres sesiones añaden orden temporal','Una secuencia de tres velas permite comparar cómo progresa el precio entre sesiones. Tres cierres crecientes no significan necesariamente tres cuerpos alcistas: el cuerpo compara cada cierre con su propia apertura. Tampoco describen por sí solos una figura completa con nombre. Consulta las tres aperturas y los tres cierres para separar esas dos afirmaciones. El patrón solo puede considerarse terminado después del tercer cierre; durante ese día todavía puede cambiar la vela y, con ella, la interpretación de toda la secuencia.','No confundas cierres crecientes con tres cuerpos verdes.'),C('En una secuencia hipotética los tres cierres suben. ¿Qué necesitas mirar para saber si las tres velas fueron verdes?','La apertura correspondiente a cada cierre.',['Solo el cierre más alto de los tres.','La apertura de la primera vela, aplicada a todas.'],'Cada cuerpo compara dos datos de su propia sesión; los cierres entre días responden a una comparación distinta.')],
 [L('No adelantar la confirmación','Supón una secuencia inventada cuyos cierres son 100, 103 y 105 euros. El cambio entre el primer y el tercero es del 5 %, y se conoce al terminar la tercera sesión. Si tu regla exige esos tres cierres, no puedes dar por hecho que compraste al precio del primero conociendo ya el tercero. Eso usaría información futura. Para probar la regla debes fijar cuándo se conoce la condición y qué precio posterior habría estado disponible para intentar ejecutar la operación.','Una condición solo puede utilizarse desde el momento en que está disponible.'),O('Ordena una prueba de una regla que necesita tres cierres.',['Esperar a que terminen las tres sesiones','Comprobar si los tres cierres cumplen la regla','Definir la primera ejecución posterior posible','Medir el resultado incluyendo costes'],'Entrar antes de que exista la condición haría que la prueba usara el futuro.')],
 [L('Medir la secuencia sin exagerarla','La distancia entre el primer y el último cierre describe el cambio de esa secuencia, no lo que necesariamente ganó una estrategia. Una subida de 100 a 105 es un 5 %; si una entrada solo puede hacerse después de 105, ese tramo ya pasó. Anotar por separado el movimiento observado y la operación hipotética impide mezclarlos. También facilita revisar secuencias fallidas: una regla debe juzgarse con el mismo procedimiento tanto si el siguiente movimiento favorece la idea como si la contradice.','El movimiento que confirma una regla no es automáticamente una ganancia capturable.'),N('Secuencia simulada: cierres 80, 82 y 84 €. ¿Qué cambio porcentual hay entre el primero y el tercero, sin atribuirlo a una operación?',5,'%','(84 − 80) / 80 × 100 = 5 %. El dato se conoce al cerrar la tercera sesión.',[84,80],'return')]
 ],['Tercera vela aún abierta','La secuencia todavía puede cambiar y no cumple una regla de tres cierres confirmados.','Tercera vela cerrada','Ya se puede revisar el patrón, pero cualquier ejecución de la regla tendría que ser posterior.']);
add('Dos techos parecidos: qué falta para hablar de giro',['Distinguir parecido visual y estructura completa','Definir confirmación e invalidación'],[
 [L('Dos máximos no cuentan toda la figura','Un posible doble techo incluye dos avances hacia una zona parecida y un retroceso intermedio. Ver dos máximos próximos es solo una parte. Para estudiar una confirmación bajista suele observarse si el precio pierde la referencia del retroceso que separa ambos intentos. Esa regla debe definirse de antemano: una mecha no equivale necesariamente a un cierre. Si el gráfico termina antes de que exista la condición, la descripción correcta es «posible figura pendiente», no un giro ya consumado.','La semejanza de dos picos no sustituye la condición de confirmación.'),M('Marca dos comprobaciones necesarias antes de dar una figura por confirmada.',['Identificar el retroceso entre los dos máximos.','Elegir el nombre que mejor encaje después de ver el futuro.','Definir qué cuenta como pérdida de la referencia.','Suponer que todos los picos de altura parecida causan caídas.'],[0,2],'La estructura intermedia y la regla de confirmación permiten evaluar la figura; el parecido solo no basta.')],
 [L('Una proyección es un escenario','Con precios inventados, imagina máximos en 120 y un valle intermedio en 110 euros. La altura de la figura es 10. Restar esa altura a 110 da una proyección de 100, si se usa ese procedimiento. No es una obligación del mercado ni un precio de ejecución garantizado. Distingue siempre el cálculo geométrico de una predicción segura. Además, los costes y el momento real de entrada pueden hacer que el resultado de una operación difiera de la proyección trazada.','Una proyección de altura es una hipótesis calculada, no un destino seguro.'),N('Figura simulada: zona superior 60 €, referencia intermedia 55 €. Si restas a 55 la altura 60 − 55, ¿qué proyección obtienes?',50,'€','Altura: 60 − 55 = 5 €. Proyección: 55 − 5 = 50 €, sin garantía de alcanzarse.',[60,55],'projection')],
 [L('Permitir que la figura no exista','Buscar una figura concreta puede llevarte a seleccionar solo las velas que la favorecen. Un tramo real puede contener máximos desiguales, un valle poco claro o una referencia que nunca se pierde. En esos casos no hace falta forzar un doble techo. Describe lo observable y lo pendiente. También anota qué subida invalidaría tu interpretación, porque un precio que supera la zona de máximos contradice la expectativa de rechazo que estabas estudiando. Aprender a descartar una etiqueta es parte del análisis.','Una figura no confirmada puede quedarse sin confirmar.'),C('La zona intermedia todavía no se ha perdido según tu regla de cierre. ¿Cómo escribes la conclusión?','Hay una posible figura, pero falta la condición que decidí exigir.',['Ya existe un giro definitivo porque los dos picos se parecen.','Puedo cambiar el criterio a una mecha anterior para declararla acertada.'],'Mantener el criterio previo evita confundir una posibilidad con una confirmación.')]
 ],['Parecido visual','Dos máximos cercanos sugieren una estructura que todavía debe revisarse.','Condición observada','Se cumple la regla definida sobre la referencia intermedia; aun así, el movimiento posterior puede fallar.']);
add('Una pausa estrecha no obliga a continuar',['Reconocer una consolidación sin anticipar la salida','Separar estrechamiento y ruptura'],[
 [L('Qué describe una consolidación','Después de un movimiento, el precio puede pasar varias sesiones dentro de una zona más estrecha. Esa pausa permite estudiar si los extremos se acercan, permanecen paralelos o pierden claridad. Los nombres como triángulo o bandera intentan describir relaciones entre referencias; no bastan para adivinar la salida. Primero observa el movimiento anterior y luego define los límites de la pausa. Un gráfico recortado solo para que parezca una figura puede ocultar el contexto que hacía falta para interpretarla.','Una pausa describe un comportamiento; la dirección de salida sigue abierta.'),P('Relaciona cada dato con la pregunta que ayuda a responder.',[['Movimiento anterior a la pausa','¿Qué contexto precede a la figura?'],['Extremos que delimitan la pausa','¿Dentro de qué zona oscila?'],['Cierre fuera de los límites','¿Se ha cumplido la regla de ruptura?']],'Contexto, límites y salida son comprobaciones distintas; ninguna debe sustituirse por el nombre de la figura.')],
 [L('Medir el estrechamiento','En un ejemplo simulado, el primer intervalo va de 90 a 110 euros y el siguiente de 96 a 104. La anchura se reduce de 20 a 8 euros. Esa reducción es una descripción de la muestra elegida. No indica qué lado se romperá ni que la salida vaya a durar. Debes comparar intervalos con una definición coherente: no mezcles el rango de varias sesiones con el de una sola solo porque así aparece una reducción más llamativa.','Compara anchuras definidas del mismo modo.'),N('Pausa simulada: el primer intervalo tiene anchura 20 € y el siguiente 8 €. ¿En cuántos euros se ha reducido la anchura?',12,'€','20 − 8 = 12 €. La reducción de anchura no fija la dirección de salida.',[20,8],'difference')],
 [L('Plantear dos salidas posibles','Una forma útil de trabajar una pausa consiste en escribir por separado qué observarías con una salida superior y con una inferior. Así no necesitas defender a toda costa una única previsión. En ambos escenarios especifica si esperas un cierre, qué referencia quedaría invalidada y qué harías si el precio vuelve dentro. El gráfico real es la base para elegir referencias, mientras que la decisión futura se mantiene como hipótesis. Esa separación evita presentar una figura conocida como si fuera una orden automática de compra.','Define alternativas antes de saber por dónde saldrá el precio.'),M('Selecciona las dos ideas compatibles con una pausa todavía abierta.',['El estrechamiento demuestra la dirección de salida.','Puedo preparar una condición para cada lado.','Debo distinguir salir de la zona y mantenerse fuera.','La figura elimina el riesgo de una falsa ruptura.'],[1,2],'Preparar ambos escenarios y revisar su permanencia fuera de la zona mantiene abierta la posibilidad de fallo.')]
 ],['Salida superior','Se revisa una condición por encima de la zona; el regreso al interior puede invalidarla.','Salida inferior','La condición es distinta y debe haberse definido sin esperar a conocer el resultado.']);
add('Salir de una zona y volver dentro',['Aplicar una regla de ruptura explícita','Reconocer un fallo sin reescribir el plan'],[
 [L('Qué significa romper en este ejercicio','Aquí llamamos ruptura a un cierre más allá de una referencia definida antes de esa sesión. Esa es nuestra regla de trabajo, no la única posible. Una mecha que cruza la línea y vuelve dentro no la cumple. Una ruptura puede fallar si después el precio regresa a la zona. Al revisar las velas reales, conserva las fechas: el nivel debe construirse con datos anteriores al cierre evaluado. Si incluyes ese mismo día para escoger la referencia, puedes alterar la prueba sin darte cuenta.','La referencia y la regla deben existir antes del dato que evalúas.'),C('Tu regla exige cerrar por encima de 100 €. Una vela simulada alcanza 103 y cierra en 99. ¿Qué ha ocurrido?','Se superó 100 durante el día, pero no se cumplió la ruptura por cierre.',['Se confirmó la regla porque basta con cualquier precio superior.','La regla se vuelve válida si el gráfico está en verde.'],'El máximo y el cierre responden a preguntas distintas. La regla elegida exige el segundo.')],
 [L('No confundir margen y beneficio','La distancia entre un cierre y la referencia muestra cuánto la ha superado, sin decir si ese margen será suficiente. Con datos inventados, un cierre de 102 sobre un nivel de 100 deja un margen de 2 euros, equivalente al 2 % de la referencia. No es una rentabilidad conseguida por una operación. La entrada, si existe, puede ser posterior y a otro precio. Mantén separados el dato que activa la idea y las condiciones de ejecución que permitirían evaluar una estrategia.','Superar una referencia no equivale a haber ganado esa diferencia.'),N('Nivel simulado de 50 € y cierre de 52 €. ¿En qué porcentaje queda el cierre por encima de la referencia de 50 €?',4,'%','(52 − 50) / 50 × 100 = 4 % sobre la referencia.',[52,50],'return')],
 [L('Cuando la lectura deja de sostenerse','Si el precio vuelve dentro de la zona, una ruptura previa no desaparece del registro. Lo que cambia es la interpretación de continuidad. Eso permite estudiar falsos intentos sin borrar las observaciones iniciales. Un procedimiento claro registra la señal, la condición posterior y el resultado, también cuando falla. No desplaza la referencia para declarar acertadas todas las salidas. Una colección que excluya los fallos mostraría una imagen mucho más favorable de la regla que la que realmente produjo la muestra.','Un fallo se registra y se estudia; no se elimina de la muestra.'),O('Ordena una revisión sin cambiar las reglas después.',['Fijar la referencia con datos anteriores','Observar si se cumple la condición de ruptura','Comprobar si el precio mantiene o pierde la zona','Registrar el resultado aunque contradiga la idea'],'Los fallos posteriores no autorizan a alterar la referencia original.')]
 ],['Permanece fuera','La condición de continuación sigue en pie dentro del horizonte elegido.','Regresa dentro','La ruptura ocurrió, pero su continuidad puede haber fallado: ambas observaciones deben conservarse.']);
add('Retrocesos: el nivel cambia con tus referencias',['Calcular una fracción de un movimiento','Comprender la dependencia de los extremos elegidos'],[
 [L('Primero se elige el movimiento','Los niveles de retroceso parten de dos extremos: el inicio y el final del movimiento que quieres estudiar. Después calculan fracciones de esa distancia. Si cambias los extremos, cambian los niveles, aunque las velas sigan siendo las mismas. En este caso conviene consultar las fechas y justificar qué tramo escoges. El 50 % se utiliza habitualmente como referencia de retroceso junto a niveles de Fibonacci, pero no es una proporción derivada de la sucesión de Fibonacci. Ninguno obliga al precio a reaccionar.','Un nivel calculado depende de las referencias elegidas y no garantiza soporte.'),P('Relaciona cada decisión con su efecto.',[['Cambiar el mínimo de partida','Cambia la distancia sobre la que se calcula'],['Usar el 50 % del tramo','Localiza su mitad'],['El precio toca el nivel','Todavía no prueba que vaya a rebotar']],'Los niveles son cálculos sobre un tramo. El comportamiento posterior sigue siendo incierto.')],
 [L('Una mitad fácil de comprobar','Con cifras simuladas, un movimiento de 80 a 100 euros tiene una amplitud de 20. Un retroceso del 50 % devuelve 10 de esos 20 y deja el precio en 90. Eso no significa que el activo haya caído un 50 % desde 100: esa caída es del 10 %. Son porcentajes con bases diferentes. Decir qué denominador utilizas evita que una cuenta correcta transmita una idea equivocada sobre la intensidad del movimiento.','Porcentaje del tramo y porcentaje del precio tienen bases distintas.'),N('Movimiento simulado de 60 a 100 €. Si retrocede el 25 % de esos 40 € de avance, ¿en qué precio queda?',90,'€','El 25 % de 40 es 10. Desde 100 retrocede hasta 90 €.',[60,100,25],'retracement')],
 [L('No buscar el nivel después del resultado','Con suficientes pares de extremos es fácil encontrar algún nivel cerca de un rebote pasado. Esa coincidencia no demuestra que lo hubieras seleccionado antes. Para estudiar la utilidad de tu lectura necesitas guardar las referencias originales y el criterio de reacción, incluyendo los días en que no ocurre. En el gráfico histórico puedes practicar el marcado, pero una evaluación honesta distingue entre explorar una idea y probar una regla ya decidida. Cambiar los extremos después del fallo pertenece a la exploración, no confirma la regla original.','Conserva los extremos originales para poder juzgar tu hipótesis.'),M('Selecciona dos prácticas que reducen el autoengaño al usar niveles.',['Anotar los dos extremos antes de mirar el desenlace.','Recalcular hasta encontrar un nivel que encaje con el rebote conocido.','Explicar si el porcentaje se aplica al tramo o al precio.','Tratar cualquier coincidencia como prueba definitiva.'],[0,2],'Referencias previas y bases explícitas hacen la lectura reproducible.')]
 ],['Mismo tramo','Conserva los extremos iniciales para revisar el resultado.','Tramo redibujado después','Es una hipótesis nueva; no demuestra que la anterior acertara.']);
add('Medias móviles: una línea que recuerda el pasado',['Calcular una media simple','Entender el retraso y los cruces'],[
 [L('De varios cierres a una referencia','Una media móvil resume varios precios recientes en un solo valor. En una media simple de tres cierres sumas esos tres valores y divides entre tres. Al avanzar un día, sale el dato más antiguo y entra el nuevo. La línea suaviza parte de las oscilaciones porque cada punto combina varios días. Precisamente por eso reacciona con retraso frente al precio. En el gráfico real se muestra una media simple de tres cierres para que puedas contrastar la línea con los datos de la tabla.','La media resume cierres conocidos; no anticipa un precio que aún no existe.'),C('En una situación hipotética, la media sigue subiendo mientras la última vela baja. ¿Sería necesariamente un error?','No: la media combina varios cierres y también depende del dato antiguo que sale.',['Sí: la media tiene que copiar siempre el último movimiento.','Sí: todas las líneas sobrepuestas deben tener la misma forma.'],'Al actualizar una media cambia toda su ventana; el último movimiento no determina por sí solo su pendiente.')],
 [L('Una cuenta que explica el retraso','En una simulación, los cierres 90, 100 y 110 tienen media 100. Si llega un cierre de 105, la nueva media de tres días utiliza 100, 110 y 105: vale 105. El precio ha bajado de 110 a 105, mientras la media ha subido de 100 a 105, porque salió el dato 90. Entender este mecanismo es más útil que memorizar que una línea ascendente «siempre confirma» una subida. La forma de la media depende de toda la ventana que la alimenta.','Para actualizar una media, identifica el dato que entra y el que sale.'),N('Cierres simulados: 10, 12 y 14 €. Llega un cierre de 16 €. ¿Cuál es la nueva media simple de tres cierres?',14,'€','Se elimina 10. (12 + 14 + 16) / 3 = 14 €.',[12,14,16],'mean')],
 [L('Un cruce necesita una regla completa','Un precio que cruza una media solo describe una relación entre dos series. En mercados laterales puede cruzarla muchas veces sin desarrollar un movimiento duradero. Antes de convertir ese cruce en una operación habría que fijar qué media, qué cierre, cuándo ejecutar, cuándo salir y qué costes descontar. Elegir después el número de días que mejor encaja con este gráfico puede mejorar la apariencia del pasado sin mejorar la siguiente decisión. La línea es una referencia para organizar datos, no una garantía.','Un cruce no sustituye las reglas de una estrategia ni su comprobación.'),O('Ordena la construcción de una prueba con una media.',['Fijar duración y tipo de media','Definir qué cruce y qué cierre cuentan','Establecer ejecución, salida y costes','Evaluar también los cruces que fallan'],'La regla completa precede a la evaluación; no se elige solo por la imagen más favorable.')]
 ],['Media corta','Responde antes y también puede cambiar de dirección con más frecuencia.','Media larga','Suaviza más datos y suele responder más lentamente a los cambios recientes.']);
add('RSI: intensidad reciente, no una orden automática',['Interpretar el RSI sin prometer giros','Diferenciar valor alto y cambio de impulso'],[
 [L('Qué compara el RSI','El RSI compara la intensidad de subidas y bajadas recientes mediante un cálculo que produce valores entre 0 y 100. Los niveles 70 y 30 se usan a menudo como referencias, no como instrucciones universales. Un valor alto puede mantenerse mientras el precio sigue subiendo. Por eso llamar «sobrecompra» a una lectura no demuestra que el activo deba caer inmediatamente. En la práctica importa el contexto, la evolución del indicador y el criterio que habías definido, no solo que haya cruzado una cifra conocida.','RSI alto no equivale a caída inmediata ni a precio fundamentalmente caro.'),M('Selecciona dos interpretaciones correctas del RSI.',['Puede mantenerse alto durante una tendencia fuerte.','Mide directamente cuánto vale un negocio.','Un nivel de referencia no garantiza el siguiente movimiento.','Pasar de 70 obliga a vender con beneficio.'],[0,2],'El RSI describe cambios de precios. No valora un negocio ni asegura un giro inmediato.')],
 [L('Practicar la relación que hay detrás','Para entender la fórmula, usemos promedios ya dados en un ejemplo simulado: subida media 3 y bajada media 1. La relación es 3 / 1 = 3; RSI = 100 − 100 / (1 + 3) = 75. Aquí no estamos construyendo un RSI real de una ventana completa: aislamos la última parte del cálculo. Para obtener una serie real habría que especificar periodo y suavizado y conservar los datos previos necesarios. Dos configuraciones distintas pueden dar lecturas diferentes.','La fórmula solo tiene sentido si sabes de dónde vienen sus promedios.'),N('Ejemplo simulado con subida media 2 y bajada media 2. Calcula RSI = 100 − 100 / (1 + 2/2).',50,'puntos','La relación es 1. 100 − 100 / 2 = 50 puntos.',[2,2],'rsi')],
 [L('Una divergencia tampoco elimina la incertidumbre','A veces el precio marca un máximo más alto mientras el RSI no supera su máximo anterior. Esa diferencia se conoce como divergencia y puede motivar una revisión del impulso. No fija cuándo ni cuánto podría cambiar el precio. Además, debes comparar extremos equivalentes y esperar a que existan los datos: escoger mínimos y máximos distintos según convenga puede fabricar divergencias. En tu nota del caso identifica las fechas y la condición adicional que exigirías antes de modificar una decisión.','Divergencia significa desacuerdo entre referencias; no un giro garantizado.'),P('Relaciona cada observación con su interpretación prudente.',[['RSI elevado durante varios días','Puede coexistir con continuación de la tendencia'],['Nuevo máximo del precio sin nuevo máximo del RSI','Posible divergencia que necesita contexto'],['RSI de 50 en el ejemplo de promedios iguales','Equilibrio entre los dos promedios dados']],'Cada lectura describe una relación concreta, sin prometer el resultado de la siguiente sesión.')]
 ],['Nivel alto sostenido','El indicador puede seguir alto mientras continúa el movimiento.','Pérdida de impulso','Un cambio en su evolución invita a revisar la idea, sin fijar un giro obligatorio.']);
add('MACD: tres elementos que no conviene mezclar',['Distinguir MACD, señal e histograma','Interpretar diferencias sin anticipar el precio'],[
 [L('Una diferencia entre medias','El MACD suele calcularse restando una media exponencial lenta de otra rápida; una configuración habitual usa 12 y 26 periodos. Una línea de señal suaviza después el propio MACD, habitualmente con nueve periodos. El histograma representa la diferencia entre ambas líneas. Conservan la unidad de los precios: euros en los pares de este caso. Son tres elementos relacionados, pero distintos. Un MACD positivo indica que la media rápida supera a la lenta, mientras que un histograma negativo indica que el MACD está por debajo de su señal. Ambas cosas pueden ocurrir a la vez.','El signo del MACD y el signo del histograma comparan parejas diferentes.'),P('Relaciona cada elemento con su comparación.',[['MACD','Media rápida menos media lenta'],['Línea de señal','Media del propio MACD'],['Histograma','MACD menos señal']],'El histograma no es la diferencia directa entre el precio y una media.')],
 [L('Los signos pueden parecer contradictorios','Tomemos una simulación: la media rápida es 105 y la lenta 100, así que el MACD vale 5. Si la señal vale 7, el histograma es 5 − 7 = −2. No hay un error: la media rápida sigue por encima de la lenta, pero el MACD queda por debajo de su propia referencia suavizada. Este ejemplo permite separar nivel y evolución reciente. No establece que el precio vaya a bajar ni sustituye la revisión del gráfico de velas.','MACD positivo e histograma negativo pueden coexistir.'),N('Ejemplo simulado en euros: MACD = 4 y señal = 6. ¿Cuál es el histograma, calculado como MACD menos señal?',-2,'€','4 − 6 = −2 €. El MACD es positivo, pero está por debajo de la señal.',[4,6],'difference')],
 [L('El cruce llega después de los datos','Como el MACD se construye con medias de precios pasados, un cruce responde a movimientos que ya han ocurrido. No es un aviso procedente del futuro. En un tramo lateral puede dar cambios frecuentes y costes si se opera cada uno. Para evaluar una regla necesitas distinguir el momento del cierre que confirma el cruce de la siguiente ejecución posible. También debes mantener fija la configuración durante la prueba, en vez de cambiarla para que elimine cada señal fallida que ves en retrospectiva.','Una señal retrasada puede ser útil como regla, pero necesita una prueba completa.'),C('Tras varios cruces fallidos, cambias los periodos hasta que el pasado queda perfecto. ¿Qué has conseguido?','Una configuración ajustada a esa muestra, pendiente de probar fuera de ella.',['Una demostración de que los próximos cruces serán rentables.','Eliminar la necesidad de contar comisiones.'],'Ajustar a los resultados conocidos puede producir sobreajuste; no prueba capacidad fuera de la muestra.')]
 ],['MACD sobre cero','La media rápida queda por encima de la lenta.','Histograma bajo cero','El MACD queda por debajo de su señal, aunque ambas medias sigan ordenadas al alza.']);
add('Bandas de Bollinger: límites que se mueven',['Relacionar media y dispersión','Evitar confundir una banda con una barrera'],[
 [L('La anchura también contiene información','Las bandas de Bollinger se sitúan alrededor de una media usando una medida de dispersión de los precios. Una configuración común utiliza veinte cierres y dos desviaciones típicas a cada lado; debe indicarse si se usa otra. Cuando los precios de la ventana se dispersan más, las bandas tienden a separarse. No son límites infranqueables. El precio puede pasar tiempo cerca de una banda o salir de ella, y ese contacto por sí solo no explica la dirección del movimiento siguiente.','Las bandas describen posición y dispersión respecto a una referencia móvil.'),M('Marca dos interpretaciones prudentes de unas bandas.',['Su anchura cambia con los datos de la ventana.','La banda superior garantiza una caída inmediata.','Un contacto necesita contexto y una regla adicional.','El precio no puede salir de las bandas.'],[0,2],'Las bandas se calculan; no impiden que los precios se negocien fuera de ellas.')],
 [L('Construir un ejemplo sencillo','Supón una media simulada de 100 euros y una desviación típica de 4. Si situamos cada banda a dos desviaciones, la superior queda en 108 y la inferior en 92. La anchura total es 16. No basta con ver que el precio vale 108 para concluir que está caro en relación con lo que produce el negocio: la herramienta no utiliza sus beneficios. Estamos midiendo posición dentro de una distribución reciente de precios, no valor económico.','La banda superior no equivale a una valoración fundamental.'),N('Ejemplo simulado: media 50 € y desviación 3 €. Con dos desviaciones a cada lado, las bandas son 56 y 44. ¿Qué anchura tienen?',12,'€','56 − 44 = 12 €. La distancia incluye ambos lados de la media.',[56,44],'difference')],
 [L('Un estrechamiento no decide la salida','Unas bandas que se aproximan muestran menor dispersión según la ventana y la fórmula utilizadas. Puede interesarte vigilar si vuelve a aumentar la amplitud, pero el estrechamiento no determina por sí solo si la salida será superior o inferior. Para estudiar una regla, deja escritos el criterio de entrada, el de invalidación y el horizonte de evaluación. Si después eliges únicamente los estrechamientos que precedieron a grandes avances, estarás ocultando las otras posibilidades que también tenía el mercado.','Menor dispersión no revela por adelantado la dirección de un movimiento posterior.'),O('Ordena una comprobación de una señal basada en bandas.',['Fijar ventana y número de desviaciones','Definir qué estrechamiento y qué salida cuentan','Aplicar las reglas a todas las ocasiones de la muestra','Comparar resultados incluyendo fallos y costes'],'Una colección de ejemplos favorables no sustituye a una muestra completa bajo criterios fijos.')]
 ],['Bandas estrechas','La dispersión reciente es menor según esa configuración.','Bandas anchas','La dispersión es mayor; su anchura por sí sola no dice si el precio subirá o bajará.']);
add('ATR: medir el movimiento que una vela no resume sola',['Calcular el rango verdadero','Interpretar el ATR como amplitud y no dirección'],[
 [L('Por qué entra el cierre anterior','El rango verdadero compara tres distancias: máximo menos mínimo, distancia del máximo al cierre anterior y distancia del mínimo a ese cierre. Escoge la mayor. Así puede recoger un desplazamiento entre sesiones que la resta entre los extremos del día no refleja completa. El ATR suaviza una serie de esos rangos; no tiene signo alcista o bajista. En este mercado continuo puede haber menos hueco entre sesiones que en una bolsa con cierre nocturno, pero la definición del cálculo es la misma.','El rango verdadero incorpora el cierre anterior; el ATR resume amplitudes.'),C('Sube el ATR mientras el precio cae. ¿Hay una contradicción?','No: el ATR mide amplitud y puede subir durante una caída.',['Sí: un ATR creciente exige precios crecientes.','Sí: el ATR mide beneficios acumulados.'],'La dirección del precio y la amplitud de los movimientos pueden evolucionar por separado.')],
 [L('Comparar las tres distancias','Utilicemos una sesión simulada con cierre anterior 100, máximo 110 y mínimo 106 euros. El rango del día es 4, la distancia entre máximo y cierre anterior es 10 y entre mínimo y cierre anterior es 6. El rango verdadero es 10, el mayor de los tres. No sumamos las distancias porque parte del movimiento se solapa. Y ese dato de un día todavía no es, por sí solo, un ATR de varios periodos: faltaría aplicar el promedio o suavizado definido.','El rango verdadero elige el máximo de tres distancias; no las suma.'),N('Sesión simulada: cierre anterior 50 €, máximo 58 € y mínimo 54 €. Compara 58−54, |58−50| y |54−50|. ¿Cuál es el rango verdadero?',8,'€','Las distancias son 4, 8 y 4. La mayor es 8 €.',[50,58,54],'true-range')],
 [L('Una medida no fija por ti la pérdida','Usar el ATR como referencia puede ayudarte a contextualizar una distancia de salida: dos euros pueden ser muchos o pocos según la amplitud reciente. Pero no determina cuánto dinero debes arriesgar ni garantiza ejecutar una orden al nivel elegido. El tamaño de la posición y los costes siguen importando. Además, comparar ATR en euros entre activos de precios muy distintos puede inducir a error. Para comparar intensidades relativas convendría expresar la amplitud respecto a una base de precio coherente y declarada.','El ATR contextualiza distancias; el tamaño de posición determina su efecto en dinero.'),M('Selecciona dos decisiones coherentes con esta medida.',['Leer ATR como una promesa de rentabilidad.','Indicar su periodo y unidad al compararlo.','Revisar tamaño y costes aunque la salida use ATR.','Suponer que una orden se ejecuta siempre al precio teórico.'],[1,2],'Sin unidad, periodo, tamaño y ejecución no puedes traducir una amplitud del mercado al riesgo de una operación.')]
 ],['ATR en euros','Sirve para contextualizar distancias del mismo activo bajo la misma configuración.','ATR relativo','Dividirlo entre una base de precio permite otra comparación; hay que indicar esa base.']);
add('ADX: fuerza sin confundirla con dirección',['Separar intensidad de tendencia y dirección','Leer referencias sin convertirlas en reglas universales'],[
 [L('Una tendencia bajista también puede tener fuerza','El ADX resume la fuerza de la tendencia según los movimientos direccionales del periodo elegido. No señala por sí mismo si esa tendencia es alcista o bajista. Por eso puede subir mientras caen los precios. Las líneas direccionales positiva y negativa, llamadas +DI y −DI, aportan otra comparación. No confundas sus cruces con el nivel del ADX. Referencias habituales como 20 o 25 ayudan a organizar una lectura, pero no son fronteras universales que funcionen igual en todos los mercados.','Un ADX alto no significa automáticamente que el precio suba.'),P('Relaciona cada dato con la pregunta que ayuda a estudiar.',[['ADX','¿Qué fuerza tiene la tendencia según esta medida?'],['Relación entre +DI y −DI','¿Qué movimiento direccional predomina en el cálculo?'],['Velas del precio','¿Qué dirección y estructura se observan?']],'ADX, líneas direccionales y precio son lecturas complementarias, no etiquetas intercambiables.')],
 [L('Comparar perfiles sin inventar una orden','Para practicar, imagina dos escenarios inventados. En A, el ADX pasa de 18 a 30 mientras la estructura de máximos y mínimos cae. En B, el ADX pasa de 30 a 18 mientras el precio avanza lentamente. A combina mayor fuerza medida con dirección bajista; B muestra menor fuerza según ese indicador, aunque el precio haya subido. No estamos diciendo cuál comprar. Estamos comprobando que puedes describir dos dimensiones diferentes sin convertir «más fuerza» en sinónimo de «mejor inversión».','Primero describe fuerza y dirección por separado.'),M('Con el escenario A simulado —ADX de 18 a 30 y estructura bajista— selecciona las dos descripciones correctas.',['El indicador de fuerza ha aumentado.','La dirección observada es bajista.','El ADX demuestra que mañana habrá un rebote.','El aumento del ADX equivale a una rentabilidad positiva.'],[0,1],'El ADX puede crecer con una tendencia bajista. No decide el siguiente cierre ni calcula la rentabilidad.')],
 [L('Qué revisar si las señales discrepan','Una lectura conjunta puede no dar una respuesta sencilla. Por ejemplo, el precio puede empezar a moverse lateralmente mientras el ADX todavía refleja datos anteriores. Eso no exige ocultar uno de los elementos. Describe el periodo del indicador, mira qué referencias del precio han cambiado y define qué observación resolvería la duda. Un indicador suavizado no tiene por qué girar el mismo día que cada vela. Mantener esa diferencia a la vista evita presentar una suma de indicadores como si fueran votos independientes sobre el futuro.','Una discrepancia puede reflejar distintas ventanas y retrasos.'),C('El precio empieza a oscilar sin dirección, pero el ADX aún es alto. ¿Cómo lo interpretas?','Reviso la ventana y el retraso del indicador junto con la estructura reciente.',['Borro las velas que contradicen al indicador.','La siguiente vela tiene que restaurar la tendencia.'],'La suavización conserva información anterior; el desacuerdo debe investigarse, no eliminarse de la descripción.')]
 ],['Fuerza creciente y precio bajista','No es una contradicción: el indicador puede acompañar una tendencia descendente.','Fuerza decreciente y precio alcista','El precio puede seguir avanzando mientras pierde fuerza según esa medida.']);
add('Precio y volumen: dos formas de combinarlos',['Comprender una media ponderada por volumen','Distinguir VWAP y OBV'],[
 [L('No todas las operaciones pesan igual','Una media ponderada por volumen da más peso a los precios asociados a mayor cantidad negociada. El VWAP combina precio por volumen y divide entre el volumen total del intervalo definido. Para obtener un VWAP exacto hacen falta datos de operaciones; con velas se suele usar una aproximación que debe identificarse. El OBV hace otra cosa: suma o resta el volumen según el cierre suba o baje frente al anterior. No es una media de precios y sus unidades no son euros.','VWAP y OBV combinan precio y volumen de maneras diferentes.'),P('Relaciona cada herramienta con lo que hace.',[['VWAP','Pondera precios por cantidad negociada'],['OBV','Acumula volumen con signo según el cambio del cierre'],['Media simple de cierres','Da el mismo peso a cada cierre incluido']],'El OBV no calcula un precio medio. La media simple no pondera las operaciones por su volumen.')],
 [L('El precio con más volumen tira de la media','En un ejemplo simulado se negocian dos unidades a 10 euros y seis a 14. La media ponderada es (2 × 10 + 6 × 14) / 8 = 13 euros. La media simple de esos dos precios sería 12 y respondería a otra pregunta. Aquí conocemos dos grupos de operaciones completos, por lo que la ponderación está bien definida. Si solo tuviéramos máximo, mínimo y cierre de una vela, no sabríamos cuántas unidades se negociaron exactamente a cada precio.','Una ponderación requiere cantidades asociadas a los precios que utilizas.'),N('Operaciones simuladas: 3 unidades a 20 € y 1 a 24 €. ¿Cuál es su precio medio ponderado por volumen?',21,'€','(3 × 20 + 1 × 24) / (3 + 1) = 21 €.',[3,20,1,24],'weighted-price')],
 [L('De dónde sale el volumen importa','El volumen de estas velas corresponde al mercado de Coinbase indicado en la fuente. Si calculases OBV con otra plataforma, la serie podría cambiar porque no se negoció exactamente la misma cantidad. También influye dónde empieza la acumulación. Por eso interesa comparar su evolución bajo una definición estable, en lugar de atribuir significado universal a un número aislado. Ni estar sobre una referencia de volumen ni ver una divergencia te permite conocer la identidad o intención de quienes participaron.','Indica mercado, intervalo y método antes de comparar indicadores de volumen.'),M('Selecciona dos detalles que debes conservar al comparar indicadores de volumen.',['La plataforma y el par utilizados.','La idea de que todos los mercados comparten el mismo volumen.','El intervalo y el método de cálculo.','La identidad supuesta de los compradores.'],[0,2],'La procedencia y el método hacen comparable la serie; el gráfico no identifica intenciones individuales.')]
 ],['Operaciones individuales','Permiten ponderar cada precio por su cantidad realmente negociada.','Velas agregadas','Pueden servir para una aproximación declarada, pero no reconstruyen todas las operaciones.']);
add('El mismo mercado visto a dos distancias',['Mantener separados los marcos temporales','Evitar usar una vela incompleta como confirmación'],[
 [L('Un retroceso diario puede convivir con un avance mayor','Una vista diaria y otra semanal resumen el mismo mercado con intervalos distintos. Varias velas diarias bajistas pueden ser un retroceso dentro de un movimiento semanal ascendente; no hay obligación de que ambas vistas den la misma etiqueta. La vela semanal agrupa apertura de la primera sesión, extremos de toda la semana y cierre de la última. Debe indicarse cuándo empieza la semana y esperar a que termine antes de usarla como una confirmación semanal cerrada.','Cada marco responde a una escala de tiempo diferente.'),C('El gráfico diario cae varios días y la estructura semanal sigue ascendente. ¿Qué interpretación es posible?','El retroceso diario puede estar dentro de una tendencia de mayor duración.',['Uno de los dos gráficos tiene que estar mal.','Puedo escoger cualquiera de los dos sin decir cuál guía mi decisión.'],'Las escalas pueden describir movimientos distintos dentro del mismo periodo general.')],
 [L('Cómo se agrupan las velas','Con datos inventados, supón tres sesiones con aperturas 100, 103 y 102; máximos 105, 108 y 106; mínimos 98, 101 y 99; y cierres 104, 102 y 105. Al agruparlas, la apertura del bloque es 100 y el cierre 105. Su máximo es 108 y su mínimo 98. No se promedian los extremos porque el bloque debe conservar los precios más alto y más bajo realmente alcanzados dentro de ese conjunto de sesiones.','Agrupar conserva primera apertura, último cierre y extremos de todo el bloque.'),N('Bloque simulado de tres días: máximos 104, 109 y 107 €; mínimos 99, 101 y 97 €. ¿Cuál es el rango del bloque completo?',12,'€','El máximo del bloque es 109 y el mínimo 97. 109 − 97 = 12 €.',[109,97],'difference')],
 [L('No cambiar de escala para esconder un fallo','Antes de evaluar una idea decide qué marco aporta contexto y cuál activa la condición concreta. Si una regla diaria falla, cambiar después al gráfico semanal para defenderla mezcla dos planes. Podrías formular una hipótesis nueva, pero habría que identificarla como tal. También debes evitar usar el cierre final de una semana antes del día en que estuvo disponible. El propósito de combinar marcos es precisar la lectura y sus límites, no encontrar una escala que siempre parezca confirmar lo que deseabas.','Cada condición necesita un marco y un momento de disponibilidad explícitos.'),O('Ordena un análisis con dos marcos temporales.',['Elegir qué marco da contexto y cuál activa la condición','Esperar al cierre exigido en cada marco','Comprobar la regla sin cambiar de escala','Registrar si se cumple o falla'],'Una condición semanal no puede confirmarse con una semana todavía abierta.')]
 ],['Semana en curso','Los máximos, mínimos y precio actual aún pueden cambiar; no es un cierre semanal confirmado.','Semana terminada','La vela ya reúne todo el bloque definido y puede usarse bajo la regla prevista.']);
add('Una señal y una ejecución son cosas distintas',['Distinguir precio observado y precio ejecutable','Incluir costes y deslizamiento en una operación'],[
 [L('La vela no promete el precio de tu orden','Una vela histórica resume precios que se negociaron, no asegura que tú hubieras podido comprar o vender cualquier cantidad exactamente a ellos. Una orden de mercado busca ejecución, mientras que una limitada fija un precio límite pero puede no ejecutarse. Una orden de salida también puede terminar a un precio distinto del nivel que la activa. Esa diferencia se llama deslizamiento. Además, una vela diaria conserva extremos, pero no dice cuál ocurrió primero: para resolver ese orden hacen falta datos intradía más detallados. Para evaluar una idea técnica debes definir la orden, el momento de envío y las condiciones de ejecución, además del dibujo del gráfico.','Un nivel señalado en el gráfico no es una ejecución garantizada.'),P('Relaciona cada elemento de un plan con lo que controla.',[['Condición de entrada','Cuándo considerar enviar una orden'],['Orden limitada','El precio límite, sin asegurar ejecución'],['Deslizamiento','La diferencia entre precio previsto y ejecutado']],'La señal organiza la decisión; la ejecución depende del mercado y de la orden utilizada.')],
 [L('La pérdida real puede ser mayor que la distancia dibujada','Imagina una operación totalmente simulada: compra en 50 euros, salida prevista en 48 y ejecución final en 47,50. La pérdida por precio es 2,50 por unidad, no 2. Si los costes totales suman 0,50 por unidad, la pérdida final es 3. El ejemplo no reproduce una operación real de este mercado ni sus tarifas actuales. Sirve para ver por qué la cuenta necesita precios ejecutados y costes definidos, en vez de quedarse con la distancia ideal del plan.','Calcula con la ejecución y los costes, no solo con el nivel deseado.'),N('Operación simulada de una unidad: compras a 20 €, vendes a 18 € y pagas 0,50 € de costes totales. ¿Cuánto pierdes? Escribe una cantidad positiva.',2.5,'€','20 − 18 + 0,50 = 2,50 € de pérdida.',[20,18,.5],'loss-with-cost')],
 [L('La secuencia intradía puede cambiar el resultado','Una vela diaria que toca tanto la salida por pérdida como el objetivo no revela necesariamente cuál se habría ejecutado primero. Usar siempre el orden más favorable exageraría el resultado. Para resolverlo necesitarías datos más detallados o una convención prudente y explícita aplicada igual a todos los casos. Además, si la señal solo se confirma al cierre, no debes ejecutar retroactivamente a un extremo anterior de esa misma vela. El momento de disponibilidad de los datos forma parte de la estrategia.','Si la vela no revela el orden de eventos, no inventes el favorable.'),M('Marca dos decisiones correctas ante una vela que toca salida y objetivo.',['Dar por ganado el objetivo porque mejora la prueba.','Reconocer que el orden puede ser desconocido.','Buscar datos más detallados o declarar una convención prudente.','Usar el máximo del día como compra conocida desde la apertura.'],[1,2],'Los extremos diarios no reconstruyen la secuencia de todas las operaciones.')]
 ],['Ejecución ideal','El precio coincide con el nivel teórico del plan; es una hipótesis que debe identificarse.','Ejecución menos favorable','El deslizamiento y los costes amplían la pérdida respecto al dibujo inicial.']);
add('El tamaño convierte una distancia en dinero',['Calcular unidades a partir de un presupuesto de pérdida','Respetar las restricciones de capital y ejecución'],[
 [L('No empieces por cuántas unidades quieres','El tamaño de posición traduce una distancia de precio a un efecto en dinero. Un procedimiento consiste en fijar un presupuesto de pérdida para el ejemplo y dividirlo entre la pérdida estimada por unidad, incluyendo costes si se han definido. Eso no convierte el presupuesto en un límite garantizado: saltos de precio, falta de liquidez o ejecución peor pueden superarlo. Tampoco elimina la restricción del capital disponible. Aquí practicamos una cuenta bajo supuestos explícitos, no una recomendación de cuánto arriesgar.','La cantidad depende de la distancia y de los supuestos de ejecución.'),C('Mantienes el mismo presupuesto de pérdida, pero duplicas la pérdida estimada por unidad. ¿Qué pasa con la cantidad calculada?','Se reduce a la mitad antes de redondeos y otras restricciones.',['Se duplica para mantener la misma oportunidad.','No cambia porque la empresa o el activo es el mismo.'],'Presupuesto dividido entre una pérdida por unidad mayor produce menos unidades.')],
 [L('Redondear sin superar el presupuesto','En una simulación, un presupuesto de 40 euros y una pérdida estimada de 3 por unidad permitirían 13,33 unidades. Si el mercado o la cuenta solo admite unidades enteras, redondear hacia arriba a 14 supera el presupuesto: 14 × 3 = 42. Redondear a 13 deja 39. Si sí se admiten fracciones, la cantidad puede ajustarse con otra precisión, pero los mínimos de orden y las comisiones pueden introducir nuevas restricciones. Explicita esas condiciones antes de dar por cerrado el tamaño.','Con unidades enteras se redondea hacia abajo para respetar esa cuenta.'),N('Simulación: presupuesto de pérdida 30 €, pérdida estimada 4 € por unidad y solo unidades enteras. ¿Cuál es la cantidad máxima según esa restricción?',7,'unidades','30 / 4 = 7,5. Se toman 7 unidades; 8 implicarían 32 €.',[30,4],'floor-ratio')],
 [L('Comprobar también el dinero necesario','La cuenta de pérdida no indica por sí sola si tienes capital para comprar la cantidad resultante. Diez unidades a 100 euros requieren 1.000 euros antes de costes, aunque la distancia hasta la salida sea pequeña. En un ejemplo sin apalancamiento debe respetarse también ese límite de compra. Si no alcanza el capital, reduce la cantidad o descarta la operación hipotética. Aumentar automáticamente el apalancamiento cambiaría el problema y añadiría riesgos que esa simple división no ha evaluado.','El tamaño final debe respetar pérdida estimada, capital y condiciones de la orden.'),O('Ordena una comprobación del tamaño sin apalancamiento.',['Definir presupuesto y pérdida estimada por unidad','Calcular cantidad y aplicar el redondeo permitido','Comprobar capital necesario y mínimos de orden','Reducir o descartar si no cumple todas las restricciones'],'Una cantidad matemáticamente compatible con el presupuesto puede exceder el capital de compra disponible.')]
 ],['Salida cercana','Con el mismo presupuesto, la fórmula permite más unidades; hay que comprobar capital y ejecución.','Salida más alejada','La cantidad calculada disminuye porque cada unidad supone una pérdida estimada mayor.']);
add('Acertar mucho puede seguir dando pérdidas',['Combinar frecuencia de acierto y tamaño de resultados','Restar costes antes de evaluar una muestra'],[
 [L('La proporción de aciertos no basta','Una estrategia puede ganar a menudo y perder dinero si sus pérdidas son mucho mayores que sus ganancias. La esperanza de una muestra combina probabilidad de ganar por ganancia media y probabilidad de perder por pérdida media, descontando los costes que no estén incluidos. Es una descripción estadística bajo esas cifras, no una promesa de la siguiente operación. Con pocas observaciones las estimaciones pueden ser muy inestables. Mantén claro si los resultados que utilizas son brutos o ya están netos de costes.','Frecuencia y tamaño deben evaluarse juntos, sin contar dos veces los costes.'),M('Selecciona dos datos que necesitas además de la proporción de aciertos.',['Ganancia media de los aciertos.','El nombre más atractivo de la estrategia.','Pérdida media de los fallos y costes no incluidos.','El color del último gráfico.'],[0,2],'La frecuencia no dice cuánto gana cada acierto ni cuánto cuesta cada fallo.')],
 [L('Una cuenta sobre operaciones simuladas','Supongamos diez operaciones inventadas: seis ganan 2 euros y cuatro pierden 4 euros, antes de costes. Las ganancias suman 12 y las pérdidas 16; el saldo es −4, aunque se acertó un 60 % de las veces. Dividido entre diez, el resultado medio bruto es −0,40 por operación. La muestra solo sirve para explicar la cuenta. No hemos probado una estrategia real sobre las velas mostradas ni estimado una probabilidad fiable del mercado con esos números.','Un 60 % de aciertos puede coexistir con un resultado negativo.'),N('Muestra simulada: 4 operaciones ganan 5 € cada una y 6 pierden 2 € cada una. Sin costes adicionales, ¿cuál es el resultado total?',8,'€','4 × 5 − 6 × 2 = 20 − 12 = 8 €.',[4,5,6,2],'expectancy-total')],
 [L('El promedio oculta el camino','Dos muestras pueden terminar con el mismo saldo y recorrer trayectorias muy distintas. Una puede empezar con varias pérdidas seguidas y otra alternarlas con ganancias. El tamaño de las caídas intermedias, la cantidad de datos y la concentración de resultados merecen revisión. Una sola operación excepcional puede sostener todo el promedio. Para estudiar una regla real necesitarías una muestra generada con criterios fijos y un periodo distinto para comprobarla; estos ejemplos de aritmética no sustituyen ese trabajo.','Mira distribución y secuencia, no solo el saldo o la media.'),P('Relaciona cada pregunta con la información que necesitas.',[['¿Con qué frecuencia gana?','Proporción de aciertos'],['¿Cuánto gana o pierde de media?','Frecuencias y magnitudes de resultados'],['¿Qué caída sufrió durante el camino?','Secuencia temporal de saldos']],'Cada medida responde a una pregunta distinta sobre la muestra.')]
 ],['Muchos aciertos pequeños','Pueden no compensar unos pocos fallos grandes.','Menos aciertos y mayores ganancias','Pueden compensar los fallos, pero hay que revisar costes, muestra y secuencia.']);
add('Probar con historia sin conocer el futuro',['Separar diseño y evaluación temporal','Construir una simulación reproducible'],[
 [L('Los datos históricos no vuelven histórica una regla','Estas velas son un registro real. La estrategia que quieras probar sobre ellas sería una simulación y necesita reglas completas: condición, ejecución, salida, costes y tamaño. Si ajustas la regla mirando toda la serie, los resultados de esa misma serie sirven para explorar, no como comprobación independiente. Una separación temporal reserva un tramo posterior que no se utiliza para elegir los parámetros. No garantiza éxito fuera de la muestra, pero evita al menos una forma directa de evaluar con las respuestas ya conocidas.','Datos reales y operaciones simuladas deben identificarse por separado.'),O('Ordena una prueba con separación temporal.',['Reservar un tramo posterior sin usarlo para elegir la regla','Diseñar la regla con el tramo inicial','Fijar parámetros, ejecución y costes','Evaluar la regla congelada en el tramo reservado'],'La evaluación pierde independencia si el tramo reservado también decide los parámetros.')],
 [L('Hacer que otra persona obtenga el mismo resultado','Una prueba reproducible guarda datos, fechas, zona horaria, fórmula y órdenes. También especifica qué ocurre si una vela toca dos niveles o si falta un dato. Elegir después la ejecución favorable cambiaría el resultado sin cambiar la etiqueta de la estrategia. La tabla de este caso permite revisar precios diarios, pero no reproduce el libro de órdenes ni todas las operaciones intradía. Esa limitación debe aparecer en el método, especialmente si las reglas dependen de qué nivel se tocó primero.','La precisión del dato limita lo que puedes afirmar sobre la ejecución.'),M('Marca dos elementos que debes documentar para reproducir la prueba.',['Zona horaria y fechas de la muestra.','Solo las operaciones que salieron bien.','Criterios de ejecución y tratamiento de eventos ambiguos.','Una elección distinta de parámetros para cada fallo.'],[0,2],'La muestra completa y las reglas de ejecución deben permanecer estables.')],
 [L('Comparar resultados netos','Supongamos una prueba inventada de veinte operaciones que obtiene 30 euros brutos. Si cada operación tiene 1 euro de coste total aún no descontado, quedan 10 euros netos. No puedes comparar directamente esos 10 con el resultado bruto de otra regla que opera muchas más veces. Usa el mismo capital, horizonte y tratamiento de costes antes de comparar. Tampoco atribuyas esta muestra ficticia a los precios reales del gráfico: es un ejemplo de cómo contabilizar, no un backtest realizado.','Una comparación necesita bases y costes consistentes.'),N('Prueba simulada: resultado bruto 40 €, doce operaciones y 2 € de coste total por operación. ¿Qué resultado neto queda?',16,'€','40 − 12 × 2 = 16 € netos.',[40,12,2],'net-trades')]
 ],['Tramo utilizado para diseñar','Ayuda a construir hipótesis, pero no es una evaluación independiente.','Tramo reservado','Permite comprobar la regla sin ajustar sus parámetros a esos resultados.']);
add('La mejor curva del pasado puede ser una trampa',['Reconocer selección de resultados y sobreajuste','Separar exploración de comprobación'],[
 [L('Probar muchas reglas cambia la interpretación','Si ensayas muchas combinaciones sobre los mismos datos, alguna puede verse excelente por casualidad. Mostrar solo la ganadora oculta cuántos intentos hubo. A ese problema se suma el sobreajuste: adaptar tantos detalles a una muestra que la regla termina describiendo peculiaridades del pasado en lugar de una relación que pueda repetirse. El gráfico real no corrige ese problema por ser real. Para evaluarlo necesitas registrar la búsqueda, limitar decisiones posteriores y comprobar la regla en datos que no determinaron la elección.','La cantidad de reglas probadas importa al interpretar a la ganadora.'),C('Pruebas cien configuraciones y publicas solo la mejor de ese mismo periodo. ¿Qué falta para sostener una conclusión?','Mostrar cómo se eligió y comprobarla en una muestra independiente.',['Añadir más decimales a la rentabilidad ganadora.','Ocultar las otras noventa y nueve configuraciones.'],'Elegir entre muchas opciones puede encontrar aciertos casuales; la evaluación independiente sigue siendo necesaria.')],
 [L('Contar lo que quedó fuera','Imagina un informe simulado que enseña ocho operaciones ganadoras y omite doce perdedoras porque «no eran representativas». Las veinte se produjeron bajo la misma regla, así que retirar las doce cambia la muestra de forma injustificada. Una exclusión válida necesitaría un criterio previo, por ejemplo un dato corrupto comprobable, aplicado por igual a ganancias y pérdidas. La cuestión no es si la curva queda bonita, sino si otra persona podría reproducirla sin saber qué resultados convenía eliminar.','Las exclusiones necesitan una razón previa independiente del resultado.'),N('Informe simulado: aparecen 8 operaciones, pero bajo la misma regla ocurrieron 20. ¿Qué porcentaje de operaciones se ha mostrado?',40,'%','8 / 20 × 100 = 40 %. Falta el 60 % y hay que conocer el motivo.',[8,20],'ratio-percent')],
 [L('Saber cuándo una comprobación deja de ser independiente','Un tramo reservado pierde su función si lo consultas repetidamente y retocas la regla para mejorarlo. En la práctica lo has incorporado al diseño. Puedes reconocerlo y reservar otra evaluación futura, pero no seguir llamándolo una prueba completamente independiente. Lo mismo ocurre al elegir mercados porque conoces de antemano dónde funcionó la idea. Documentar intentos fallidos, cambios y criterios no garantiza un resultado rentable; sí permite entender qué demuestra realmente la prueba y qué incertidumbre queda.','Cuando ajustas con el resultado de evaluación, ese resultado pasa a formar parte del diseño.'),M('Marca dos señales de que una supuesta evaluación independiente se ha contaminado.',['Cambiar parámetros tras consultar repetidamente el tramo reservado.','Fijar la regla antes de abrir ese tramo.','Elegir únicamente mercados conocidos por dar resultados favorables.','Publicar también los resultados negativos.'],[0,2],'Ambas decisiones utilizan el desenlace para seleccionar la regla o la muestra.')]
 ],['Regla congelada','Se evalúa sin retocarla con las respuestas del tramo reservado.','Regla retocada tras cada resultado','El tramo se ha convertido en parte del diseño y requiere otra comprobación.']);
add('Un diario para recordar lo que de verdad sabías',['Registrar una hipótesis antes del resultado','Distinguir buena decisión y resultado favorable'],[
 [L('Una nota fechada evita recuerdos convenientes','Después de conocer un movimiento parece fácil explicar por qué «era evidente». Un diario escrito antes ayuda a conservar lo que realmente sabías: fecha, mercado, marco, observaciones, hipótesis, invalidación y condiciones de ejecución. La nota no tiene que ser larga, pero sí revisable. En este caso puedes detenerte en el último día visible y formular una idea sin consultar el día siguiente. No se trata de acertar una historia retrospectiva, sino de poder comparar una decisión previa con los datos que lleguen después.','Guarda la información disponible y el criterio antes de conocer el desenlace.'),O('Ordena una revisión apoyada en un diario.',['Anotar datos conocidos y la hipótesis antes del resultado','Guardar condiciones de invalidación y ejecución','Registrar el desenlace sin reescribir la nota inicial','Evaluar tanto el proceso como el resultado'],'Reescribir la previsión después de verla fallar impide aprender de la decisión original.')],
 [L('Un beneficio no demuestra que el proceso fuera bueno','Una operación inventada puede terminar con beneficio aunque haya incumplido el plan, igual que una regla bien definida puede sufrir una pérdida prevista. El resultado económico importa, pero una sola observación no valida ni invalida todo el proceso. Para aprender, separa dos preguntas: si se siguieron las reglas y qué ocurrió finalmente. Esta separación permite detectar errores de ejecución que quedaron ocultos por un mercado favorable, además de no abandonar una hipótesis solo por un fallo aislado.','Evalúa proceso y resultado por separado antes de sacar conclusiones generales.'),P('Relaciona cada situación simulada con lo que permite concluir.',[['Beneficio tras ignorar el límite del plan','Resultado favorable con una desviación del proceso'],['Pérdida dentro de las condiciones previstas','Resultado negativo que no prueba por sí solo un error de ejecución'],['Cambiar la nota después del resultado','Se pierde la evidencia de la hipótesis original']],'El dinero ganado o perdido no cuenta por sí solo cómo se tomó la decisión.')],
 [L('Las categorías deben definirse antes','Si quieres medir cumplimiento del plan, define previamente qué cuenta como una desviación. En una muestra simulada de diez decisiones, ocho respetan el procedimiento y dos lo incumplen. La tasa de cumplimiento es 80 %, sin importar cuántas ganaron dinero. No cambies la clasificación de un incumplimiento porque al final salió bien. Conservar ambos datos permite revisar si los fallos pertenecían a la idea, a su ejecución o a una interpretación ambigua de las reglas que necesita aclararse.','Cumplimiento del plan y porcentaje de aciertos son métricas distintas.'),N('Diario simulado: 12 decisiones, de las que 9 siguen el procedimiento definido. ¿Qué porcentaje cumple el plan?',75,'%','9 / 12 × 100 = 75 %. No es la proporción de operaciones ganadoras.',[9,12],'ratio-percent')]
 ],['Anotación previa','Permite saber qué información y qué condiciones guiaron la decisión.','Explicación posterior','Puede ayudar a aprender, pero debe distinguirse de lo que se había previsto.']);
add('De varios indicadores a una idea comprensible',['Asignar una función a cada herramienta','Evitar contar señales dependientes como pruebas independientes'],[
 [L('Más líneas no significan más pruebas','Una media móvil y el MACD se construyen con precios anteriores; no son dos observadores totalmente independientes. Añadir varias herramientas parecidas puede repetir la misma información con otra forma. Antes de dibujar, decide qué pregunta responde cada una: estructura para contexto, una condición concreta para revisar la entrada, amplitud para contextualizar distancias y un plan para gestionar la incertidumbre. Una hipótesis revisable también identifica el marco temporal, qué dato la activa, cuál la invalidaría y qué supuestos de ejecución y pérdida se han fijado. Si una herramienta no cambia ninguna pregunta ni decisión, quizá solo esté añadiendo ruido a la lectura del caso.','Cada herramienta debe tener una función; varias pueden repetir información.'),M('Selecciona dos decisiones que simplifican un análisis sin perder rigor.',['Definir qué pregunta responde cada indicador.','Contar cada línea como una prueba independiente aunque use los mismos datos.','Separar contexto, condición e invalidación.','Añadir indicadores hasta que desaparezcan todas las dudas.'],[0,2],'Una función clara y la separación de condiciones ayudan más que acumular señales relacionadas.')],
 [L('Convertir una opinión en condiciones verificables','Una frase como «se ve bien» no permite revisar nada. En una simulación, una hipótesis podría decir: «solo la consideraré si cierra sobre 100; la revisaré si vuelve bajo 95; antes de operar comprobaré tamaño y costes». No garantiza un beneficio, pero enumera condiciones observables. Si falta alguna, el plan está incompleto. La redacción también debe indicar el marco temporal: un cierre de cinco minutos no sustituye al cierre diario que exigía la hipótesis.','Una hipótesis operativa necesita condiciones observables y un marco definido.'),P('Relaciona cada frase simulada con su función.',[['La estructura semanal da el contexto','Marco de la hipótesis'],['Exigir un cierre diario sobre la referencia','Condición de activación'],['Revisar la idea al perder la referencia contraria','Invalidación']],'Contexto, activación e invalidación responden a preguntas diferentes y no deben mezclarse.')],
 [L('También puedes terminar sin una operación','Un análisis puede concluir que faltan datos, que las referencias son ambiguas o que el riesgo no encaja con las restricciones del ejemplo. Eso es un resultado válido. El objetivo no es obligarte a emitir una compra o una venta cada vez que abres un gráfico. En el caso real, termina con una descripción de lo que se observa, una hipótesis condicionada y lo que aún no sabes. Si después llegan nuevos datos, revisa esa nota en lugar de tratar la incertidumbre como un error que había que ocultar.','No operar puede ser coherente cuando las condiciones no están completas.'),C('El contexto parece favorable, pero tu condición de entrada no se ha cumplido. ¿Qué conclusión respeta el plan?','Mantener la hipótesis pendiente y esperar el dato que falta.',['Dar por cumplida la condición porque otros indicadores gustan.','Eliminar el criterio que estorba y presentar la misma idea como confirmada.'],'Una condición no se vuelve cierta por acumular señales favorables de otro tipo.')]
 ],['Herramientas con funciones distintas','Contexto, activación y riesgo quedan separados y se pueden revisar.','Varias versiones de la misma información','Pueden dar apariencia de confirmación sin aportar evidencia independiente.']);
add('Un informe final que admite más de un desenlace',['Integrar precio, actividad, condiciones y límites','Revisar la hipótesis sin inventar certezas'],[
 [L('El caso completo empieza por delimitar los datos','Antes de cerrar este recorrido, revisa el origen, la moneda y las fechas del gráfico. Identifica qué puedes describir directamente y qué requiere una interpretación. Una conclusión completa no necesita usar todos los indicadores: necesita que sus afirmaciones estén apoyadas por los datos que cita. Si se habla de una tendencia, señala referencias; si se habla de actividad, indica la comparación de volumen; si se plantea una operación, sepárala del registro histórico y declara sus supuestos de ejecución.','Un informe claro permite distinguir fuente, observación, interpretación y simulación.'),P('Relaciona cada parte del informe con su función.',[['Fuente, fechas y moneda','Delimitar los datos utilizados'],['Referencias observadas en las velas','Sostener la descripción del mercado'],['Condiciones para lo que ocurra después','Formular una hipótesis revisable']],'La procedencia y las referencias sostienen hechos; las condiciones describen escenarios todavía abiertos.')],
 [L('Comparar planes bajo los mismos supuestos','Para practicar una última cuenta, usemos dos planes completamente simulados. A arriesga 2 euros por unidad y usa 10 unidades; B arriesga 4 y usa 5. Bajo ejecución exacta y sin costes, ambos exponen 20 euros a la salida definida. Eso no los hace iguales en probabilidad, volatilidad, capital requerido o calidad de señal. Igualar una dimensión ayuda a comparar, pero no borra las demás. En una evaluación real habría que añadir los costes y la posible diferencia entre nivel previsto y ejecución.','Igual pérdida teórica no significa que dos planes sean equivalentes.'),N('Planes simulados sin costes y con ejecución exacta: A usa 6 unidades con pérdida de 3 € por unidad; B usa 3 unidades con pérdida de 6 €. ¿Cuál es la pérdida teórica de cada plan?',18,'€','A: 6 × 3 = 18. B: 3 × 6 = 18 €. Solo se ha igualado esa dimensión.',[6,3],'product')],
 [L('Terminar con condiciones, no con una promesa','Una conclusión responsable puede explicar qué escenario apoyan los datos actuales, qué dato lo debilitaría y qué información falta. Si el mercado toma otra dirección, habrá una hipótesis previa que revisar. Esa estructura vale para tendencias, rangos y cambios de comportamiento, y evita que cada desenlace parezca haber estado previsto desde el principio. Los gráficos históricos de este caso permiten practicar la lectura, pero no demuestran una estrategia rentable ni justifican trasladar automáticamente una decisión simulada a dinero real.','La conclusión final debe seguir siendo comprobable aunque el mercado te contradiga.'),M('Selecciona las dos frases que deberían estar en un informe revisable.',['Qué dato futuro me haría cambiar de interpretación.','La garantía de que el mercado cumplirá la figura.','Qué información falta o qué limitación tiene la muestra.','La certeza de que el pasado se repetirá exactamente.'],[0,2],'Una invalidación y unos límites explícitos permiten aprender tanto de aciertos como de errores.')]
 ],['El escenario se sostiene','Se cumplen las condiciones declaradas; el resultado económico sigue dependiendo de ejecución y evolución posterior.','El escenario falla','Se registra el fallo y se revisa la hipótesis sin reescribir lo que se sabía al principio.']);

assert.equal(definitions.length,29);
export {definitions,market,C,M,N,P,O,L,F,flow,round,fmt,course,track};
